-- ============================================================================
-- UDSM e-Clearance & Transcript MIS — Complete Staff & Missing Reference Sync
-- ============================================================================
-- File           : deploy/03_missing_staff_and_reference_sync.sql
-- Purpose        : Fast, lightweight (<40 KB), idempotent phpMyAdmin sync script:
--                    1. Ensures ALL 144 institutional staff accounts exist & are
--                       active/unlocked (includes dept.coet.mie@udsm.ac.tz, all 61
--                       Department Officers, all 20 Principals/Lecturers/Supervisors
--                       incl. DUCE & MUCE, dpgs.deputy, and 6 Station Secretaries).
--                    2. Seeds missing UDSM residential Halls & Hostels (10 rows).
--                    3. Preserves passwords on already-existing staff accounts while
--                       setting default password 'Clearance@2026!' on newly added rows.
-- Default Pass   : Clearance@2026! (BCrypt 10 rounds — rotate after first login)
-- Target Engine  : MySQL 8.0.19+ (uses VALUES (...) AS new_row — zero #1287 warnings)
-- Security       : Contains ZERO student rows (will NOT touch live student data).
-- ============================================================================

SET NAMES utf8mb4;
SET TIME_ZONE = '+00:00';
START TRANSACTION;

